-- 14. Automatic Teacher Sync & Trigger
-- Synchronize any existing Teacher user accounts to the teachers table
SELECT 
  id, 
  name, 
  'General English' as subject, 
  350000 as hourly_rate, 
  COALESCE(branch_id, (SELECT id FROM public.branches LIMIT 1)) as branch_id
FROM "users"
WHERE role = 'Teacher'
ON CONFLICT (id) DO NOTHING;

-- Function to automatically insert teacher profile on user insert/update
CREATE OR REPLACE FUNCTION public.handle_new_teacher()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.role = 'Teacher' THEN
    IF NOT EXISTS (SELECT 1 FROM public.teachers WHERE id = NEW.id) THEN
      VALUES (
        NEW.id,
        NEW.name,
        'General English',
        350000,
        COALESCE(NEW.branch_id, (SELECT id FROM public.branches LIMIT 1))
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_teacher_user_created ON public.users;
CREATE TRIGGER on_teacher_user_created
  AFTER INSERT OR UPDATE OF role, name, branch_id ON public.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_teacher();

-- Seeding completed successfully!